static void Benchmark(string name, Action action, int warmup = 100_000, int iterations = 1_000_000)
{
    // Warmup
    for (int i = 0; i < warmup; i++) action();

    // Measure allocations
    GC.Collect();
    GC.WaitForPendingFinalizers();
    GC.Collect();
    long memBefore = GC.GetTotalAllocatedBytes(true);
    for (int i = 0; i < 1000; i++) action();
    long memAfter = GC.GetTotalAllocatedBytes(true);
    double allocPerOp = (memAfter - memBefore) / 1000.0;

    // Measure time - run multiple rounds and take the median
    var times = new double[5];
    for (int round = 0; round < times.Length; round++)
    {
        var sw = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++) action();
        sw.Stop();
        times[round] = sw.Elapsed.TotalNanoseconds / iterations;
    }
    Array.Sort(times);
    double medianNs = times[times.Length / 2];

    string timeStr = medianNs < 1000 ? $"{medianNs:F2} ns" : $"{medianNs / 1000:F2} us";
    string allocStr = allocPerOp < 1 ? "0 B" : $"{allocPerOp:F0} B";
    Console.WriteLine($"{name,-25} {timeStr,12} {allocStr,12}");
}
